gmv(){return"\u0645\u062d\u0641\u0638\u0629 \u0627\u0644\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u0622\u0644\u064a\u0629"},
gqy(){return"\u0627\u0644\u0639\u0645\u0644\u0627\u0621 \u064a\u062b\u0642\u0648\u0646 \u0628\u0646\u0627"},
