gnG(){return"\u0627\u0644\u0623\u0641\u0636\u0644 \u0628\u0627\u0644\u0646\u0633\u0628\u0629 \u0644\u0646\u0641\u0642\u0627\u062a\u0643 \u0627\u0644\u064a\u0648\u0645\u064a\u0629 \u0648\u0635\u0646\u062f\u0648\u0642 \u0627\u0644\u0637\u0648\u0627\u0631\u0626 \u0627\u0644\u062e\u0627\u0635 \u0628\u0643\u060c \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0633\u062a\u0639\u062f\u064b\u0627 \u0644\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631."},
gmu(){return"\u0633\u0644\u0645 \u0627\u0644\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u0622\u0644\u064a"},
gnQ(){return"\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u062e\u0632\u0627\u0646\u0629 \u0627\u0644\u0623\u0645\u0631\u064a\u0643\u064a\u0629"},
gnF(){return"\u0628\u062f\u0639\u0645 \u0645\u0646 \u0627\u0644\u062d\u0643\u0648\u0645\u0629 \u0627\u0644\u0641\u064a\u062f\u0631\u0627\u0644\u064a\u0629\u060c \u064a\u0645\u0643\u0646 \u0644\u0633\u0646\u062f\u0627\u062a \u0627\u0644\u062e\u0632\u0627\u0646\u0629 \u062a\u062d\u0642\u064a\u0642 \u0645\u0639\u062f\u0644 \u062b\u0627\u0628\u062a \u0648\u062a\u0639\u062a\u0628\u0631 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0623\u0643\u062b\u0631 \u0627\u0644\u0627\u0633\u062a\u062b\u0645\u0627\u0631\u0627\u062a \u0623\u0645\u0627\u0646\u064b\u0627 \u0641\u064a \u0627\u0644\u0639\u0627\u0644\u0645."},
gnb(){return"\u0627\u0633\u062a\u062b\u0645\u0627\u0631 \u0627\u0644\u0645\u0624\u0634\u0631"},
gnH(){return"\u062a\u0645 \u062a\u0635\u0645\u064a\u0645 method \u0627\u0644\u0630\u064a \u062a\u0645 \u0627\u062e\u062a\u0628\u0627\u0631\u0647 \u0639\u0628\u0631 \u0627\u0644\u0632\u0645\u0646 \u0644\u0632\u064a\u0627\u062f\u0629 \u0627\u0644\u0639\u0648\u0627\u0626\u062f \u0625\u0644\u0649 \u0623\u0642\u0635\u0649 \u062d\u062f \u0639\u0644\u0649 \u0627\u0644\u0645\u062f\u0649 \u0627\u0644\u0637\u0648\u064a\u0644\u060c \u0628\u064a\u0646\u0645\u0627 \u0646\u0642\u0648\u0645 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0628\u0625\u062f\u0627\u0631\u0629 \u0627\u0644\u0645\u062e\u0627\u0637\u0631 \u0646\u064a\u0627\u0628\u0629\u064b \u0639\u0646\u0643."},
