gnB(){return"\u0623\u0639\u062f \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
glw(){return"\u062c\u0627\u0631 \u0627\u0644\u062a\u062d\u0645\u064a\u0644..."},
