gnY(){return"\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627"},
gqF(){return"Coinetra \u064a\u0646\u0645\u0648 \u0628\u0633\u0631\u0639\u0629. \u064a\u0631\u062c\u0649 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0623\u0642\u0631\u0628 \u0645\u0643\u062a\u0628 \u0625\u0642\u0644\u064a\u0645\u064a \u0644\u062f\u064a\u0643 \u0644\u0645\u0639\u0631\u0641\u0629 \u0643\u064a\u0641 \u064a\u0645\u0643\u0646\u0646\u0627 \u0627\u0644\u0645\u0633\u0627\u0639\u062f\u0629 \u0641\u064a \u062c\u0644\u0628 \u0623\u0633\u0647\u0645 \u062e\u0627\u0635\u0629 \u0639\u0627\u0644\u064a\u0629 \u0627\u0644\u0645\u0633\u062a\u0648\u0649 \u0625\u0644\u064a\u0643."},
goj(){return"\u0623\u0631\u0633\u0644 \u0644\u0646\u0627 \u0631\u0633\u0627\u0644\u0629"},
gzI(){return"\u0627\u0633\u0645\u0643"},
