gw7(){return"\u0916\u093e\u0924\u0947 \u0914\u0930 \u0930\u0942\u091f\u093f\u0902\u0917 \u0928\u0902\u092c\u0930\u094b\u0902 \u0915\u0947 \u0938\u093e\u0925 \u092a\u0948\u0938\u0947 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u093f\u0924 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092c\u093f\u0932\u094b\u0902 \u0915\u093e \u092d\u0941\u0917\u0924\u093e\u0928 \u0915\u0930\u0947\u0902, \u0938\u093e\u0925 \u0939\u0940 \u0939\u092e\u093e\u0930\u0947 \u092e\u094b\u092c\u093e\u0907\u0932 \u0910\u092a \u0938\u0947 \u0928\u093f\u0903\u0936\u0941\u0932\u094d\u0915 \u091a\u0947\u0915 \u092d\u0947\u091c\u0947\u0902 \u0914\u0930 \u091c\u092e\u093e \u0915\u0930\u0947\u0902\u0964"},
gyG(){return"\u092e\u093f\u0928\u091f\u094b\u0902 \u092e\u0947\u0902 \u0928\u093f\u0935\u0947\u0936 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u0923"},
gyH(){return"\u092e\u093f\u0928\u091f\u094b\u0902 \u092e\u0947\u0902 Coinetra \u0928\u093f\u0935\u0947\u0936 \u0916\u093e\u0924\u0947 \u092e\u0947\u0902 \u0928\u0915\u0926\u0940 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u093f\u0924 \u0915\u0930\u0947\u0902, \u0914\u0930 \u0905\u092a\u0928\u0947 \u0926\u0940\u0930\u094d\u0918\u0915\u093e\u0932\u093f\u0915 \u0927\u0928 \u0915\u094b \u0914\u0930 \u092d\u0940 \u0905\u0927\u093f\u0915 \u092e\u0947\u0939\u0928\u0924 \u0938\u0947 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0947\u0902, \u092f\u0925\u093e\u0936\u0940\u0918\u094d\u0930\u0964"},
gpB(){return"\u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u092c\u091a\u0924 \u0914\u0930 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u0923"},
gpC(){return"\u0905\u092a\u0928\u0940 \u0938\u094d\u0935\u092f\u0902 \u0915\u0940 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u092f\u094b\u091c\u0928\u093e\u090f\u0902 \u092c\u0928\u093e\u090f\u0902 \u0914\u0930 Coinetra \u0915\u0947 \u0938\u093e\u0925 \u0905\u092a\u0928\u0947 \u092c\u091a\u0924 \u0932\u0915\u094d\u0937\u094d\u092f\u094b\u0902 \u0914\u0930 \u0928\u093f\u0935\u0947\u0936\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0927\u0928 \u0938\u094d\u0925\u093e\u0928\u093e\u0902\u0924\u0930\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0906\u0935\u0930\u094d\u0924\u0940 \u0939\u0938\u094d\u0924\u093e\u0902\u0924\u0930\u0923 \u0938\u0947\u091f \u0915\u0930\u0947\u0902\u0964"},
