gyT(){return"FDIC \u092c\u0940\u092e\u093e \u092e\u0947\u0902 $8 \u092e\u093f\u0932\u093f\u092f\u0928 \u0924\u0915"},
gou(){return"$1 \u0938\u0947 \u0915\u092e\u093e\u0908 \u0936\u0941\u0930\u0942 \u0915\u0930\u0947\u0902"},
gu4(){return"\u0939\u092e \u0915\u0948\u0938\u0947 \u0922\u0947\u0930 \u0939\u094b \u091c\u093e\u090f\u0902?\n\u0905\u092a\u0928\u0947 \u0932\u093f\u090f \u0926\u0947\u0916\u0932\u094b\u0964"},
gqB(){return"APY \u0926\u0930\u0947\u0902 \u0914\u0930 \u0938\u0942\u091a\u0940\u092c\u0926\u094d\u0927 \u0905\u0928\u094d\u092f \u091c\u093e\u0928\u0915\u093e\u0930\u0940 21 \u091c\u0941\u0932\u093e\u0908, 2025 \u0924\u0915 \u0939\u0948\u0902 \u0914\u0930 \u092a\u0930\u093f\u0935\u0930\u094d\u0924\u0928 \u0915\u0947 \u0905\u0927\u0940\u0928 \u0939\u0948\u0902\u0964 \u092a\u093e\u0930\u0902\u092a\u0930\u093f\u0915 \u092c\u0948\u0902\u0915 \u092c\u091a\u0924 \u0916\u093e\u0924\u094b\u0902 \u092e\u0947\u0902 \u0915\u0941\u0932 \u0938\u0902\u092a\u0924\u094d\u0924\u093f \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u0936\u0940\u0930\u094d\u0937 \u0905\u092e\u0947\u0930\u093f\u0915\u0940 \u092c\u0948\u0902\u0915 \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902\u0964 \u0939\u093e\u0908 \u092f\u0940\u0932\u094d\u0921 \u0915\u0948\u0936 \u092e\u0948\u0928\u0947\u091c\u092e\u0947\u0902\u091f \u0916\u093e\u0924\u094b\u0902 \u0915\u094b \u0909\u0926\u094d\u092f\u094b\u0917-\u0905\u0917\u094d\u0930\u0923\u0940 \u0909\u091a\u094d\u091a APYs, \u092e\u091c\u092c\u0942\u0924 \u092c\u0940\u092e\u093e \u0938\u0941\u0930\u0915\u094d\u0937\u093e \u0914\u0930 \u0915\u092e \u092f\u093e \u092c\u093f\u0928\u093e \u0915\u093f\u0938\u0940 \u0916\u093e\u0924\u093e \u0936\u0941\u0932\u094d\u0915 \u0915\u0947 \u0938\u0902\u092f\u094b\u091c\u0928 \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u091a\u0941\u0928\u093e \u0917\u092f\u093e \u0925\u093e, \u0914\u0930 \u092f\u0947 Coinetra \u0915\u0947 \u0915\u0948\u0936 \u0916\u093e\u0924\u0947 \u0938\u0947 \u0938\u092c\u0938\u0947 \u0905\u0927\u093f\u0915 \u0924\u0941\u0932\u0928\u0940\u092f \u0939\u0948\u0902\u0964 \u0939\u093e\u0908 \u092f\u0940\u0932\u094d\u0921 \u092c\u091a\u0924 \u0916\u093e\u0924\u094b\u0902 \u0915\u094b \u092c\u0948\u0902\u0915\u0930\u0947\u091f \u0914\u0930 \u0928\u0947\u0930\u0921\u0935\u093e\u0932\u0947\u091f \u091c\u0948\u0938\u0947 \u0932\u094b\u0915\u092a\u094d\u0930\u093f\u092f \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0935\u093f\u0924\u094d\u0924 \u0938\u092e\u0940\u0915\u094d\u0937\u093e \u092a\u094d\u0932\u0947\u091f\u092b\u093e\u0930\u094d\u092e\u094b\u0902 \u0926\u094d\u0935\u093e\u0930\u093e \u0936\u0940\u0930\u094d\u0937 \u0930\u0947\u091f\u093f\u0902\u0917 \u0915\u0947 \u0906\u0927\u093e\u0930 \u092a\u0930 \u091a\u0941\u0928\u093e \u0917\u092f\u093e \u0925\u093e\u0964"},
