gty(){return"\ud504\ub85c\uadf8\ub7a8 \uc740\ud589\uc744 \ud1b5\ud55c \ucd5c\ub300 800\ub9cc \ub2ec\ub7ec\uc758 FDIC \ubcf4\ud5d8"},
