gpT(){return"Magnus\ub294 Coinetra\uc758 \uc0ac\ubaa8\ud380\ub4dc\ub97c \uc6b4\uc601\ud558\uc5ec \ud22c\uc790\uc790\ub4e4\uc774 \ucd5c\uace0 \uc218\uc900\uc758 \uc0ac\ubaa8\ud380\ub4dc\uc5d0 \uafb8\uc900\ud788 \uc811\uadfc\ud560 \uc218 \uc788\ub3c4\ub85d \ubcf4\uc7a5\ud569\ub2c8\ub2e4... [\uc804\uccb4 \uc18c\uac1c \ud14d\uc2a4\ud2b8\ub294 \uc5ec\uae30] ... Magnus\ub294 \uc5ec\uac00 \uc2dc\uac04\uc5d0 \uc2a4\ud3ec\uce20, \uc694\ub9ac, \uc0ac\uc9c4\uc5d0 \ub300\ud55c \uc5f4\uc815\uc744 \uc2e4\ucc9c\ud569\ub2c8\ub2e4."},
gxY(){return"\ucd5c\uace0 \uc0c1\uc5c5 \ucc45\uc784\uc790"},
gpU(){return"Marine\uc740 \ub9c8\ucf00\ud305, \uc9c1\uc811 \ud310\ub9e4 \ubc0f \uace0\uac1d \uc11c\ube44\uc2a4\uc5d0 \uad00\ud55c \ubaa8\ub4e0 Coinetra \ud65c\ub3d9\uc758 \uae00\ub85c\ubc8c \ubc29\ud5a5\uc744 \uc124\uc815\ud558\ub294 \ucc45\uc784\uc744 \ub9e1\uace0 \uc788\uc2b5\ub2c8\ub2e4... [\uc804\uccb4 \uc57d\ub825\uc740 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.] ... \uadf8\ub140\ub294 Le Havre University\uc758 \uad6d\uc81c \ubb38\uc81c \ub300\ud559\uc5d0\uc11c \uc601\uc5b4 \ubc0f \uc911\uad6d\uc5b4 \ubd81\uacbd\uc5b4\uc640 \ud568\uaed8 \uad6d\uc81c \ube44\uc988\ub2c8\uc2a4, \uc544\uc2dc\uc544 \ubb38\uc81c \uc11d\uc0ac \ud559\uc704\ub97c \ubc1b\uc558\uc2b5\ub2c8\ub2e4."},
