gx3(){return"\uadc0\ud558\uc758 \uac1c\uc778 \ub370\uc774\ud130 \ucc98\ub9ac \uc81c\ud55c\uc744 \uc694\uccad\ud558\uc2ed\uc2dc\uc624."},
gx0(){return"\ub370\uc774\ud130 \uc774\ub3d9\uc131\uc744 \uc694\uccad\ud558\uc138\uc694."},
gx4(){return"\uc5b8\uc81c\ub4e0\uc9c0 \ub3d9\uc758\ub97c \ucca0\ud68c\ud558\uc2ed\uc2dc\uc624(\ucc98\ub9ac\uac00 \ub3d9\uc758\uc5d0 \uae30\ubc18\ud55c \uacbd\uc6b0)."},
gx5(){return"\uc774\ub7ec\ud55c \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\ub824\uba74 \uc544\ub798 \uc81c\uacf5\ub41c \uc5f0\ub77d\ucc98 \uc815\ubcf4\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub2f9\uc0ac\uc5d0 \ubb38\uc758\ud558\uc2ed\uc2dc\uc624. \uadc0\ud558\uc758 \uc694\uccad\uc5d0 \uc751\ub2f5\ud558\uae30 \uc804\uc5d0 \uadc0\ud558\uc758 \uc2e0\uc6d0\uc744 \ud655\uc778\ud574\uc57c \ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4."},
gwD(){return"\ucfe0\ud0a4"},
gwC(){return"\ub2f9\uc0ac\ub294 \ucfe0\ud0a4 \ubc0f \uc720\uc0ac\ud55c \ucd94\uc801 \uae30\uc220\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc11c\ube44\uc2a4 \ud65c\ub3d9\uc744 \ucd94\uc801\ud558\uace0 \ud2b9\uc815 \uc815\ubcf4\ub97c \ubcf4\uc720\ud569\ub2c8\ub2e4. \uadc0\ud558\ub294 \ube0c\ub77c\uc6b0\uc800\uc5d0 \ubaa8\ub4e0 \ucfe0\ud0a4\ub97c \uac70\ubd80\ud558\uac70\ub098 \ucfe0\ud0a4\uac00 \uc804\uc1a1\ub418\ub294 \uc2dc\uae30\ub97c \ud45c\uc2dc\ud558\ub3c4\ub85d \uc9c0\uc2dc\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \ucfe0\ud0a4\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\uc73c\uba74 \ub2f9\uc0ac \uc11c\ube44\uc2a4\uc758 \uc77c\ubd80\ub97c \uc0ac\uc6a9\ud558\uc9c0 \ubabb\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4."},
gwx(){return"\uc544\ub3d9\uc758 \uac1c\uc778\uc815\ubcf4 \ubcf4\ud638"},
gww(){return'\ub2f9\uc0ac \uc11c\ube44\uc2a4\ub294 18\uc138 \ubbf8\ub9cc("\uc5b4\ub9b0\uc774")\uc5d0\uac8c\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub2f9\uc0ac\ub294 18\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\ub85c\ubd80\ud130 \uac1c\uc778 \uc2dd\ubcc4 \uc815\ubcf4\ub97c \uace0\uc758\ub85c \uc218\uc9d1\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uadc0\ud558\uac00 \ubd80\ubaa8 \ub610\ub294 \ubcf4\ud638\uc790\uc774\uace0 \uadc0\ud558\uc758 \uc790\ub140\uac00 \ub2f9\uc0ac\uc5d0 \uac1c\uc778 \ub370\uc774\ud130\ub97c \uc81c\uacf5\ud588\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uace0 \uc788\ub294 \uacbd\uc6b0 \ub2f9\uc0ac\uc5d0 \ubb38\uc758\ud558\uc2ed\uc2dc\uc624.'},
