gyj(){return"\uc77c\ubc18 \uc99d\uad8c\ubc95 \uc6d0\uce59"},
gyl(){return"\uc0ac\uc6a9\uc790\uc758 \uc758\ubb34"},
gyf(){return"\uac1c\uc778 \uc815\ubcf4 \ubcf4\ud638 \ubc0f \ubcf4\ud638"},
gyd(){return"\ud50c\ub7ab\ud3fc\uc758 \uc18c\uc720\uad8c"},
