gmE(){return"\ucd9c\uc2dc \uc608\uc815"},
gtK(){return"\ube44\ubc00\ubc88\ud638 \ucc3e\uae30\ub97c \ud074\ub9ad\ud588\uc2b5\ub2c8\ub2e4(\uad6c\ud604\ub418\uc9c0 \uc54a\uc74c)"},
ox(a){return"\uc0c1\ud0dc\uac00 "+a+"\ub85c \uc5c5\ub370\uc774\ud2b8\ub418\uc5c8\uc2b5\ub2c8\ub2e4."},
